<script>
(() => { const fmt = n => new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(n); async function refresh(){try{const [statsRes,lowRes,txRes]=await Promise.all([fetch('{{ route('api.dashboard.stats') }}',{headers:{Accept:'application/json'}}),fetch('{{ route('api.products.low-stock') }}',{headers:{Accept:'application/json'}}),fetch('{{ route('api.transactions.recent') }}',{headers:{Accept:'application/json'}})]);if(!statsRes.ok||!lowRes.ok||!txRes.ok)throw new Error('Server returned '+[statsRes.status,lowRes.status,txRes.status].join('/'));const stats=(await statsRes.json()).data;const low=(await lowRes.json()).data;const tx=(await txRes.json()).data;setAnimated('stat-total-products',stats.total_products);setAnimated('stat-low-stock',low.filter(p=>p.quantity>0).length);setAnimated('stat-out-of-stock',low.filter(p=>p.quantity<=0).length);setAnimated('stat-inventory-value',fmt(stats.inventory_value));document.getElementById('last-updated').textContent=new Date(stats.last_updated).toLocaleString();document.getElementById('low-stock-list').innerHTML=low.length?low.map(p=>`<p><a href="/products/${p.id}">${escapeHtml(p.name)}</a> — ${p.quantity} left (reorder at ${p.reorder_level})</p>`).join(''):'<p>No products at or below reorder level.</p>';document.getElementById('recent-transactions').innerHTML=tx.length?tx.map(t=>`<tr><td>${escapeHtml(t.product)}</td><td>${escapeHtml(t.type.replaceAll('_',' '))}</td><td>${escapeHtml(t.quantity)}</td><td>${escapeHtml(t.user)}</td></tr>`).join(''):'<tr><td colspan="4">No transactions recorded yet.</td></tr>';document.getElementById('polling-error').textContent='';}catch(e){document.getElementById('polling-error').textContent='Automatic refresh failed. Your current page data is still visible; refresh the page or check the server.';}}function setAnimated(id,value){const el=document.getElementById(id);el.classList.remove('stat-updated');void el.offsetWidth;el.textContent=value;el.classList.add('stat-updated');}function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}setInterval(refresh,30000);})();
</script>
